use num_bigint::{BigInt,BigUint};use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeSet,fs,path::Path};
const ROOT:&str="/home/ubuntu/src/zopro-perf-work/affine-redc-offset176";const B:i128=1<<52;const MASK:u64=(1<<52)-1;
const PRIMES:[&str;2]=["21888242871839275222246405745257275088696311157297823662689037894645226208583","21888242871839275222246405745257275088548364400416034343698204186575808495617"];
const NAMES:[&str;5]=["mul_minus","mul_minus_sum","mul_double_minus_sum","sum2_minus","difference2_minus"];
fn u(x:u64)->BigUint{BigUint::from(x)}fn z(x:i128)->BigInt{BigInt::from(x)}
fn integer(v:&[i128])->BigInt{v.iter().rev().fold(z(0),|a,&b|(a<<52usize)+z(b))}
fn digits(x:&BigUint)->[u64;5]{let mut n=x.clone();std::array::from_fn(|_|{let d=(&n&u(MASK)).to_u64_digits().first().copied().unwrap_or(0);n>>=52usize;d})}
fn positive(x:BigInt,p:&BigInt)->BigInt{((x%p)+p)%p}
fn inv(a:&BigUint,p:&BigUint)->BigUint{let(mut r,mut s)=(BigInt::from(p.clone()),BigInt::from(a.clone()));let(mut x,mut y)=(z(0),z(1));while s!=z(0){let q=&r/&s;(r,s)=(s.clone(),r-&q*s);(x,y)=(y.clone(),x-q*y);}assert_eq!(r,z(1));positive(x,&BigInt::from(p.clone())).to_biguint().unwrap()}
fn halves(a:u64,b:u64)->(i128,i128){assert!(a<=MASK&&b<=MASK);let x=a as i128*b as i128;(x&(B-1),x>>52)}
struct Field{p:BigUint,two:BigUint,r:BigUint,pinv:BigUint,rinv:BigUint,pd:[u64;5],inv:u64}
impl Field{fn new(p:BigUint)->Self{let r=u(1)<<256usize;let wb=u(1)<<52usize;Self{two:&p*u(2),pd:digits(&p),pinv:inv(&p,&r),rinv:inv(&(&r%&p),&p),inv:(&wb-inv(&(&p%&wb),&wb)).to_u64_digits()[0],p,r}}}
#[derive(Default)]struct Count{outputs:u64,rows:u64,negative_coefficients:u64,negative_carries:u64,reduce4:u64,reduce2:u64,noncanonical:u64,max_pre:i128,max_raw:i128,max_signed:i128,hash:Sha256}
fn raw_cios(input:&[BigUint;4],f:&Field,fused:bool,c:&mut Count)->([i128;5],BigUint){let products=if fused{2}else{1};let ds=input.each_ref().map(digits);let total=&input[0]*&input[1]+if fused{&input[2]*&input[3]}else{u(0)};let mut t=[0i128;6];let mut full=total.clone();for row in 0..5{for part in 0..products{let(a,b)=(&ds[2*part],&ds[2*part+1]);for j in 0..5{let(l,h)=halves(a[j],b[row]);t[j]+=l;t[j+1]+=h;}}
 let bits=if row==4{48usize}else{52};let radix=1i128<<bits;let q=((t[0]as u128*f.inv as u128)&((radix-1)as u128))as u64;
 let low=(&full&((u(1)<<bits)-u(1))).to_u64_digits().first().copied().unwrap_or(0);assert_eq!(q,((low as u128*f.inv as u128)&((radix-1)as u128))as u64);
 let m=if row==4{q<<4}else{q};let carry=(t[0]+radix-1)/radix+halves(m,f.pd[0]).1;
 for j in 1..5{let(l,h)=halves(q,f.pd[j]);t[j]+=l;t[j+1]+=h;}
 assert!(t.iter().all(|&v|v>=0&&v<64*B));c.max_pre=c.max_pre.max(*t.iter().max().unwrap());
 assert_eq!((&full+u(q)*&f.p)%u(1<<bits),u(0));full=(&full+u(q)*&f.p)>>bits;
 if row<4{t[1]+=carry;t=[t[1],t[2],t[3],t[4],t[5],0];}else{let mask48=(1i128<<48)-1;let out=[carry+((t[1]&mask48)<<4),(t[1]>>48)+((t[2]&mask48)<<4),(t[2]>>48)+((t[3]&mask48)<<4),(t[3]>>48)+((t[4]&mask48)<<4),(t[4]>>48)+(t[5]<<4)];assert_eq!(integer(&out),BigInt::from(full.clone()));assert!(out[..4].iter().all(|&x|x>=0&&x<3*B));assert!(out[4]>=0&&out[4]<B);c.max_raw=c.max_raw.max(*out.iter().max().unwrap());
 let qtotal=(&f.r-(&total*&f.pinv)%&f.r)%&f.r;assert_eq!(full,(&total+qtotal*&f.p)/&f.r);c.rows+=5;return(out,full);}}
 unreachable!()}
fn execute(input:&[BigUint;6],f:&Field,mode:usize,c:&mut Count)->BigUint{assert!(mode<5);for x in &input[..4]{assert!(x<=&f.two);}for x in &input[4..]{assert!(x<&f.p);}let mut product: [BigUint;4]=std::array::from_fn(|i|input[i].clone());if mode==4{product[2]=&f.two-&product[2];}let fused=mode>=3;let(raw,full)=raw_cios(&product,f,fused,c);assert!(full<if fused{&f.p*u(3)}else{f.two.clone()});
 let sum=mode==1||mode==2;let scale=if mode==2{2}else{1};let bias=if sum{f.two.clone()}else{f.p.clone()};let bd=digits(&bias);let xd=digits(&input[4]);let yd=digits(&input[5]);let mut out=std::array::from_fn::<_,5,_>(|i|scale*raw[i]+bd[i]as i128-xd[i]as i128-if sum{yd[i]as i128}else{0});
 for &v in &out{assert!(v>-2*B&&v<8*B);c.negative_coefficients+=u64::from(v<0);c.max_signed=c.max_signed.max(v.abs());}
 let before=integer(&out);let exact=BigInt::from(full.clone())*z(scale)+BigInt::from(bias)-BigInt::from(input[4].clone())-if sum{BigInt::from(input[5].clone())}else{z(0)};assert_eq!(before,exact);assert!(exact>=z(0));assert!(exact<BigInt::from(&f.p*u(if mode==2{6}else{4})));
 for j in 0..4{let carry=out[j].div_euclid(B);c.negative_carries+=u64::from(carry<0);out[j]=out[j].rem_euclid(B);out[j+1]+=carry;assert!(out[j+1].abs()<8*B);}
 assert_eq!(integer(&out),exact);assert!(out.iter().all(|&v|v>=0&&v<B));let mut value=exact.to_biguint().unwrap();if mode==2&&value>=&f.p*u(4){value-=&f.p*u(4);c.reduce4+=1;}if value>=f.two{value-=&f.two;c.reduce2+=1;}assert!(value<f.two);c.noncanonical+=u64::from(value>=f.p);
 let p=BigInt::from(f.p.clone());let a=BigInt::from(input[0].clone());let b=BigInt::from(input[1].clone());let d=BigInt::from(input[2].clone())*BigInt::from(input[3].clone());let numerator=a*b+if mode==3{d}else if mode==4{-d}else{z(0)};let expected=positive(numerator*BigInt::from(f.rinv.clone())*z(scale)-BigInt::from(input[4].clone())-if sum{BigInt::from(input[5].clone())}else{z(0)},&p);assert_eq!(BigInt::from(&value%&f.p),expected);
 for limb in digits(&value){c.hash.update(limb.to_le_bytes());}c.outputs+=1;value}
fn edge(f:&Field)->Vec<BigUint>{let mut out=BTreeSet::new();for x in[u(0),u(1),&f.p-u(1),f.p.clone(),&f.p+u(1),&f.two-u(1),f.two.clone()]{out.insert(x);}for bit in[1usize,51,52,53,63,64,103,104,105,127,128,155,156,157,191,192,207,208,209,251,252,253]{let x=u(1)<<bit;for n in[&x-u(1),x.clone(),&x+u(1)]{if n<=f.two{out.insert(n);}}}out.into_iter().collect()}
fn random(domain:&str,index:usize,p:&BigUint)->BigUint{let mut h=Sha256::new();h.update(domain.as_bytes());h.update((index as u64).to_le_bytes());BigUint::from_bytes_le(&h.finalize())%p}
fn main(){let output=format!("{ROOT}/model-result.json");assert!(!Path::new(&output).exists());let mut results=vec![];for (prime,decimal)in PRIMES.iter().enumerate(){let f=Field::new(BigUint::parse_bytes(decimal.as_bytes(),10).unwrap());assert!(&f.p*u(4)<f.r);let edges=edge(&f);let n=edges.len();let mut counts: [Count;5]=std::array::from_fn(|_|Count::default());let mut chains: [[BigUint;6];5]=std::array::from_fn(|m|std::array::from_fn(|j|random(&format!("affine-offset-{prime}-{m}-{j}"),0,if j<4{&f.two}else{&f.p})));
 let rows=n*n+2048+512;for row in 0..rows{for mode in 0..5{let input:[BigUint;6]=if row<n*n{std::array::from_fn(|j|{let x=match j{0=>edges[row/n].clone(),1=>edges[row%n].clone(),2=>edges[(row/n+7*(row%n)+1)%n].clone(),3=>edges[(11*(row/n)+row%n+3)%n].clone(),4=>edges[(3*(row/n)+row%n)%n].clone()%&f.p,_=>edges[(row/n+5*(row%n)+1)%n].clone()%&f.p};x})}else if row<n*n+2048{std::array::from_fn(|j|random(&format!("affine-offset-{prime}-{j}"),row,if j<4{&f.two}else{&f.p}))}else{chains[mode].clone()};let value=execute(&input,&f,mode,&mut counts[mode]);if row>=n*n+2048{chains[mode].rotate_left(1);for j in 0..6{chains[mode][j]=&chains[mode][j]%if j<4{&f.two}else{&f.p};}chains[mode][0]=value;}}}
 let ops=counts.into_iter().enumerate().map(|(mode,c)|json!({"mode":NAMES[mode],"outputs":c.outputs,"CIOS_cancellation_rows":c.rows,"negative_offset_coefficients":c.negative_coefficients,"negative_carries":c.negative_carries,"reduce4p":c.reduce4,"reduce2p":c.reduce2,"noncanonical_results":c.noncanonical,"max_prepack_coefficient":c.max_pre.to_string(),"max_raw_coefficient":c.max_raw.to_string(),"max_signed_offset_coefficient":c.max_signed.to_string(),"output_digest":format!("{:x}",c.hash.finalize())})).collect::<Vec<_>>();results.push(json!({"prime":if prime==0{"Fq"}else{"Fr"},"edge_count":n,"rows_per_operation":rows,"operations":ops}));}
 let result=json!({"complete":true,"radix_bits":256,"cases":results,"negative_signed_carry_required":true,"raw_output_limbs_normalized":true,"raw_output_strictly_below_2p":true,"canonical_offsets_required":true,"new_proofs":0,"production_changed":false,"native_qualification_selected":true,"native_speed_selected":false,"goal_complete":false});fs::write(output,serde_json::to_vec_pretty(&result).unwrap()).unwrap();println!("Exact deferred-offset model PASS: both primes, five operations, raw CIOS and independent REDC/residue/carry checks");}
